var XWiki = (function (XWiki) {
  define("proj-manag-presets", {
    prefix: "projectmanagement.presets.create.modal.",
    keys: [
      "confirm",
      "input.name.label",
      "input.isMultiple.label",
      "title"
    ],
  });
  require(['jquery', 'xwiki-meta', 'xwiki-l10n!proj-manag-presets'], function ($, xm, l10n) {
    XWiki.ProjManagNewPreset = Class.create(XWiki.widgets.ModalPopup, {
      initialize: function ($super, trigger) {
        trigger[0].observe('click', this.showDialog.bindAsEventListener(this));
        // this.urlTemplate = trigger.up().next('input[type=hidden]').value;

        this.client = trigger.data('client');
        this.input = new Element('input', { type: 'text', name: 'title' });
        this.checkbox = new Element('input', { type: 'checkbox', name: 'isMultiple' });
        this.addButton = new Element('button', {
          class: 'btn btn-primary'
        });
        this.addButton.innerHTML = l10n.get('confirm');

        var container = $('<div></div>')
          .attr('id', 'proj-manag-preset-popup')
          .addClass('xform')
          .append('<dl>');
        container
           .find('dl')
            .append($('<dt>', { text: l10n.get('input.name.label') }))
            .append($('<dd>').append(this.input))
            .append($('<dt>', { text: l10n.get('input.isMultiple.label') }))
            .append($('<dd>').append(this.checkbox));
        container.append(this.addButton);

        $super(container[0], {
          show: { method: this.showDialog, keys: [] },
          add: { method: this._onAdd, keys: ['Enter'] }
        }, {
          title: l10n.get('title'),
          verticalPosition: 'top'
        });
      },
      createDialog: function ($super, event) {
        this.addButton.observe('click', this._onAdd.bind(this));
        $super(event);
      },
      showDialog: function ($super, event) {
        $super(event);
        this.input.clear().focus();
      },
      _onAdd: function () {
        if (this.input.value != '') {
          // We use the global flag because we need to replace both the page name and its title.
          var docRef = XWiki.Model.resolve('ProjectManagement.Code.Presets.Preset' + Date.now(), XWiki.EntityType.DOCUMENT, XWiki.currentDocument.getDocumentReference());
          var doc = new XWiki.Document(docRef);
          var createUrl = doc.getURL('edit', new URLSearchParams({
            template: 'ProjectManagement.Code.Presets.PresetTemplate',
            title: this.input.value,
            isMultiple: this.checkbox.checked ? 1 : 0,
            client: this.client,
            form_token: xm.form_token
          }).toString());
          window.self.location = createUrl;
        } else {
          this.input.focus();
        }
      }
    });

    function init() {
      var actionBox = $('#proj-manag-create-preset');
      if (actionBox) {
        new XWiki.ProjManagNewPreset(actionBox);
        return true;
      }
      return false;
    }
    (XWiki.domIsLoaded && init()) || document.observe('xwiki:dom:loaded', init);

    return XWiki;
  });
  return XWiki;

}(XWiki || {}));
